//! The generated pytest suite, run for real.
//!
//! For a kernel, a compose and a forbidden-scenario golden the suite is
//! generated by the binary and run with pytest against a hand-written
//! implementation that conforms (every test passes), one that does not (the
//! tests that reach the defect fail, at the step that shows it), and unwired
//! (every test fails; with `--allow-unwired` every test is skipped).
//!
//! pytest is required: `python3 -m pip install pytest`, or point
//! `FSL_TESTGEN_PYTHON` at an interpreter that has it. The test fails rather
//! than passing without having run anything.

mod support;

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use std::process::Command;

use support::{cases, run, scratch};

struct Run {
    code: i32,
    passed: BTreeSet<String>,
    failed: BTreeSet<String>,
    skipped: usize,
    text: String,
}

fn python() -> String {
    std::env::var("FSL_TESTGEN_PYTHON").unwrap_or_else(|_| "python3".to_owned())
}

fn implementations() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/pytest_run")
}

/// Generate the suite of `case`, bind `Adapter` to `adapter` (a
/// `module.Class` of `tests/pytest_run`) when one is given, and run pytest.
fn run_suite(case: &str, flags: &[&str], adapter: Option<&str>) -> Run {
    let golden = cases()
        .into_iter()
        .find(|golden| golden.name == case)
        .expect("golden case");
    let mut args = vec!["generate", "--target", "pytest"];
    args.extend(flags);
    let generated = run(&args, &golden.input);
    assert_eq!(generated.status.code(), Some(0), "{case}: generate");
    let mut suite = String::from_utf8(generated.stdout).expect("UTF-8 suite");
    let directory = scratch("pytest-run");
    if let Some(adapter) = adapter {
        let (module, class) = adapter.split_once('.').expect("module.Class");
        std::fs::copy(
            implementations().join(format!("{module}.py")),
            directory.join(format!("{module}.py")),
        )
        .expect("copy the implementation");
        // What a user does by editing the class: `Adapter` now is theirs.
        suite.push_str(&format!("\n\nfrom {module} import {class} as Adapter\n"));
    }
    std::fs::write(directory.join("test_conformance.py"), suite).expect("write the suite");
    let output = Command::new(python())
        .args([
            "-m",
            "pytest",
            "-rA",
            "--tb=short",
            "--color=no",
            "-p",
            "no:cacheprovider",
            "test_conformance.py",
        ])
        .env("PYTHONDONTWRITEBYTECODE", "1")
        .env_remove("PYTEST_ADDOPTS")
        .current_dir(&directory)
        .output()
        .unwrap_or_else(|error| panic!("cannot run {} -m pytest: {error}", python()));
    let text = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        !text.contains("No module named pytest"),
        "pytest is required to run this test: {} -m pip install pytest",
        python()
    );
    let named = |outcome: &str| {
        text.lines()
            .filter_map(|line| line.strip_prefix(outcome))
            .filter_map(|line| line.trim().strip_prefix("test_conformance.py::"))
            .map(|line| line.split(" - ").next().unwrap_or(line).to_owned())
            .collect::<BTreeSet<_>>()
    };
    Run {
        code: output.status.code().expect("pytest exit code"),
        passed: named("PASSED"),
        failed: named("FAILED"),
        skipped: text
            .lines()
            .filter(|line| line.starts_with("SKIPPED"))
            .map(|line| {
                // `SKIPPED [N] file:line: reason`
                line.split(['[', ']'])
                    .nth(1)
                    .and_then(|count| count.parse::<usize>().ok())
                    .expect("skip count")
            })
            .sum(),
        text,
    }
}

fn names(tests: &[&str]) -> BTreeSet<String> {
    tests.iter().map(|&test| test.to_owned()).collect()
}

const CART_TESTS: [&str; 4] = [
    "test_scenario_cover_add_to_cart",
    "test_scenario_cover_remove_from_cart",
    "test_scenario_cover_checkout",
    "test_random_walk_conformance",
];
const BANK_TESTS: [&str; 5] = [
    "test_scenario_cover_bank_settle",
    "test_scenario_cover_deposit_audited",
    "test_scenario_cover_withdraw_audited",
    "test_scenario_reach_bank_Settled",
    "test_random_walk_conformance",
];
const ORDER_TESTS: [&str; 5] = [
    "test_scenario_cover_pay",
    "test_scenario_cover_ship",
    "test_scenario_cover_cancel",
    "test_scenario_forbidden_FB_1",
    "test_random_walk_conformance",
];

#[test]
fn a_conforming_implementation_passes_every_test() {
    for (case, adapter, tests) in [
        ("kernel", "cart.Conforming", &CART_TESTS[..]),
        ("compose", "bank_system.Conforming", &BANK_TESTS[..]),
        ("forbidden", "orders.Conforming", &ORDER_TESTS[..]),
    ] {
        let run = run_suite(case, &[], Some(adapter));
        assert_eq!(run.code, 0, "{case}:\n{}", run.text);
        assert_eq!(run.passed, names(tests), "{case}:\n{}", run.text);
        assert!(run.failed.is_empty() && run.skipped == 0, "{case}");
        // Wired, `--allow-unwired` changes nothing: every test still runs.
        let run = run_suite(case, &["--allow-unwired"], Some(adapter));
        assert_eq!(run.code, 0, "{case}:\n{}", run.text);
        assert_eq!(run.passed, names(tests), "{case}:\n{}", run.text);
        assert_eq!(run.skipped, 0, "{case}");
    }
}

/// The overselling cart never takes an item from stock. The tests that check
/// out fail, each at the first state after a checkout; the others pass.
#[test]
fn a_cart_that_oversells_fails_at_the_checkout() {
    let run = run_suite("kernel", &[], Some("cart.NonConforming"));
    assert_eq!(run.code, 1, "{}", run.text);
    assert_eq!(
        run.failed,
        names(&[
            "test_scenario_cover_checkout",
            "test_random_walk_conformance",
        ]),
        "{}",
        run.text
    );
    assert_eq!(
        run.passed,
        names(&[
            "test_scenario_cover_add_to_cart",
            "test_scenario_cover_remove_from_cart",
        ])
    );
    // The scenario fails on the expectation that follows `checkout`.
    assert!(
        run.text.contains(
            "    _assert_partial_expected(adapter.observe(), {'stock': {'0': 0, '1': 1}, 'cart': {'0': None, '1': None}})\n"
        ),
        "{}",
        run.text
    );
    // The walk's second step (index 1) is the first checkout.
    assert!(
        run.text
            .contains("AssertionError: random walk step 1: checkout {'u': 1}"),
        "{}",
        run.text
    );
}

/// The double-counting bank leaves settled funds pending. `deposit_audited`
/// alone still passes; everything that settles fails at the settle.
#[test]
fn a_bank_that_double_counts_fails_at_the_settle() {
    let run = run_suite("compose", &[], Some("bank_system.NonConforming"));
    assert_eq!(run.code, 1, "{}", run.text);
    assert_eq!(
        run.failed,
        names(&[
            "test_scenario_cover_bank_settle",
            "test_scenario_cover_withdraw_audited",
            "test_scenario_reach_bank_Settled",
            "test_random_walk_conformance",
        ]),
        "{}",
        run.text
    );
    assert_eq!(run.passed, names(&["test_scenario_cover_deposit_audited"]));
    // The walk's third step (index 2) is the first settle.
    assert!(
        run.text
            .contains("AssertionError: random walk step 2: bank.settle {}"),
        "{}",
        run.text
    );
}

/// The forbidden step is asserted as rejected: an implementation that
/// accepts a cancellation after shipping fails exactly that scenario.
#[test]
fn an_accepted_forbidden_step_fails_the_forbidden_scenario() {
    let run = run_suite("forbidden", &[], Some("orders.NonConforming"));
    assert_eq!(run.code, 1, "{}", run.text);
    assert_eq!(
        run.failed,
        names(&["test_scenario_forbidden_FB_1"]),
        "{}",
        run.text
    );
    assert_eq!(run.passed.len(), 4);
    assert!(
        run.text
            .contains("    _assert_rejected(result, 'requires_failed')\n"),
        "{}",
        run.text
    );
    assert!(
        run.text.contains("assert result.get('ok') is False"),
        "{}",
        run.text
    );
}

#[test]
fn an_unwired_suite_fails_and_skips_only_with_allow_unwired() {
    for (case, tests) in [
        ("kernel", &CART_TESTS[..]),
        ("compose", &BANK_TESTS[..]),
        ("forbidden", &ORDER_TESTS[..]),
    ] {
        let run = run_suite(case, &[], None);
        assert_eq!(run.code, 1, "{case}:\n{}", run.text);
        assert_eq!(run.failed, names(tests), "{case}:\n{}", run.text);
        assert!(run.passed.is_empty() && run.skipped == 0, "{case}");
        // Each failure report carries the message.
        assert!(
            run.text
                .matches("\nadapter not wired: implement Adapter.reset/step/observe")
                .count()
                >= tests.len(),
            "{case}:\n{}",
            run.text
        );

        let run = run_suite(case, &["--allow-unwired"], None);
        assert_eq!(run.code, 0, "{case}:\n{}", run.text);
        assert_eq!(run.skipped, tests.len(), "{case}:\n{}", run.text);
        assert!(run.passed.is_empty() && run.failed.is_empty(), "{case}");
    }
}
